message.content:
{
  "events": [
    {
      "key": "sao_smith_metal",
      "title": "부러진 시험검",
      "story": "리즈벳의 공방에서 시험하던 검이 부러졌다. 바로 더 강한 검을 달라고 해도 재료는 저절로 생기지 않는다. 희귀 금속을 찾는 의뢰에서 당신이 맡을 일을 정한다.",
      "intro": "리즈벳의 공방에서 시험하던 검이 부러졌다. 바로 더 강한 검을 달라고 해도 재료는 저절로 생기지 않는다. 희귀 금속을 찾는 의뢰에서 당신이 맡을 일을 정한다.",
      "choices": [
        {
          "label": "금속 수송 장비 비용을 낸다",
          "result": "수송용 특수 케이스를 확보했다. 리즈벳이 안전한 운송을 위해 필요한 장비를 준비한다. 카드: 리즈벳(가공의 완성도) 획득. [금액: 220 소모]"
        },
        {
          "label": "키리토와 위험 구역의 재료를 찾는다",
          "result": "키리토의 빠른 기동성을 빌려 험난한 지형을 돌파한다. 위험을 무릅쓰고 희귀 재료를 채굴한다. 카드: 키리토(빈틈을 잇는 검) 획득."
        },
        {
          "label": "에길에게 남은 부품을 넘긴다",
          "result": "쓸모없어진 파편을 에길에게 매각한다. 상인인 그는 이를 가치 있게 평가하며 보상을 건넨다. 카드: 없음. [골드: 220 획득]"
        }
      ]
    },
    {
      "key": "sao_smith_return",
      "title": "공방으로 돌아온 재료",
      "story": "수송을 준비한 재료가 공방에 도착했다. 리즈벳은 가공을 맡고 당신에게는 작업장의 다른 일이 남았다. 완성된 경험을 어디에 쓸지 정한다.",
      "intro": "수송을 준비한 재료가 공방에 도착했다. 리즈벳은 가공을 맡고 당신에게는 작업장의 다른 일이 남았다. 완성된 경험을 어디에 쓸지 정한다.",
      "choices": [
        {
          "label": "가공을 돕고 키리토의 검 운용을 관찰한다",
          "result": "리즈벳의 손놀림을 돕는 동시에 키리토의 검술을 분석한다. 실전에서 유용한 검술의 궤적을 익힌다. 카드: 키리토(빈틈을 잇는 검) 획득."
        },
        {
          "label": "아스나에게 안전한 작업 구역을 부탁한다",
          "result": "아스나에게 주변 경계와 안전 확보를 요청한다. 그녀의 지휘 아래 안정적인 작업 환경을 구축한다. 카드: 아스나(섬광의 사선) 획득. [금액: 200 소모]"
        },
        {
          "label": "남은 재료를 정리하고 대금을 받는다",
          "result": "정리된 재료를 최종 검수하고 의뢰비를 수령한다. 깔끔한 뒷정리로 정당한 보상을 얻는다. 카드: 없음. [골드: 250 획득, 포션: 1 획득]"
        }
      ]
    },
    {
      "key": "sao_companion_herb",
      "title": "작은 동료를 위한 꽃",
      "story": "시리카는 잃은 피나를 되찾을 수 있다는 꽃을 찾아야 한다. 당신이 얻는 카드는 원작 동료를 실제 소환하지 않는다. 길을 함께 열지, 돌아올 준비를 맡을지 정한다.",
      "intro": "시리카는 잃은 피나를 되찾을 수 있다는 꽃을 찾아야 한다. 당신이 얻는 카드는 원작 동료를 실제 소환하지 않는다. 길을 함께 열지, 돌아올 준비를 맡을지 정한다.",
      "choices": [
        {
          "label": "시리카와 보급을 준비한다",
          "result": "시리카와 함께 필요한 물자를 챙기며 이동한다. 그녀의 꼼꼼한 보급 준비로 기반을 다진다. 카드: 시리카(돌아갈 길의 동료) 획득. [금액: 180 소모]"
        },
        {
          "label": "클라인과 주변 몬스터를 다른 길로 유도한다",
          "result": "클라인의 전술을 활용해 적의 시선을 분산시킨다. 동료들이 안전하게 이동할 수 있는 경로를 확보한다. 카드: 클라인(함께 맞서는 간격) 획득."
        },
        {
          "label": "키리토와 위험한 길을 먼저 확인한다",
          "result": "키리토에게 앞장서서 길을 개척해달라고 요청한다. 그의 정찰을 통해 안전한 경로를 확보한다. 카드: 키리토(돌아와 전한 경고) 획득."
        },
        {
          "label": "꽃을 운반할 도구를 맡고 대금을 받는다",
          "result": "운반용 수레를 제작하여 대여한다. 효율적인 운반 시스템을 구축하고 수고비를 받는다. 카드: 없음. [골드: 230 획득]"
        }
      ]
    },
    {
      "key": "sao_rabbit_table",
      "title": "요리할 수 없는 희귀 고기",
      "story": "희귀한 래빗의 고기를 얻었지만 당신은 제대로 요리할 수 없다. 아스나는 일부를 함께 먹는 조건으로 요리를 맡을 수 있다고 한다. 모두가 칼을 갈기 전에 식탁을 준비한다.",
      "intro": "희귀한 래빗의 고기를 얻었지만 당신은 제대로 요리할 수 없다. 아스나는 일부를 함께 먹는 조건으로 요리를 맡을 수 있다고 한다. 모두가 칼을 갈기 전에 식탁을 준비한다.",
      "choices": [
        {
          "label": "재료비를 내고 아스나와 식탁을 준비한다",
          "result": "아스나에게 재료비를 일부 건네며 요리를 부탁한다. 그녀의 손맛으로 든든한 식사를 준비한다. 카드: 아스나(공략 전의 식탁) 획득. [금액: 170 소모]"
        },
        {
          "label": "에길에게 팔고 골드를 챙긴다",
          "result": "고기를 상인 에길에게 넘겨 현금화한다. 식사는 포기하지만 즉각적인 자금을 확보한다. 카드: 없음. [골드: 280 획득]"
        },
        {
          "label": "클라인과 경계 구역을 나눠 식사를 지킨다",
          "result": "클라인과 역할을 나누어 식사 시간을 확보한다. 경계를 유지하며 안전하게 식사를 마친다. 카드: 클라인(함께 맞서는 간격) 획득."
        }
      ]
    },
    {
      "key": "sao_boss_warning",
      "title": "되돌아온 정찰대",
      "story": "보스 방을 살펴본 키리토와 아스나가 준비 없이 들어가지 말라고 경고한다. 경고를 듣고도 진입하려는 사람들에게 필요한 것은 허세가 아니라 정찰 결과와 보급이다.",
      "intro": "보스 방을 살펴본 키리토와 아스나가 준비 없이 들어가지 말라고 경고한다. 경고를 듣고도 진입하려는 사람들에게 필요한 것은 허세가 아니라 정찰 결과와 보급이다.",
      "choices": [
        {
          "label": "키리토와 위험 구역의 정찰을 이어간다",
          "result": "키리토와 함께 보스 방 주변을 더 상세히 조사한다. 정확한 위치와 적의 배치를 파악한다. 카드: 키리토(돌아와 전한 경고) 획득."
        },
        {
          "label": "아스나와 진입 순서를 정리한다",
          "result": "아스나의 지휘 아래 효율적인 진입 동선을 짠다. 체계적인 계획으로 초기 피해를 줄인다. 카드: 아스나(섬광의 사선) 획득. [금액: 220 소모]"
        },
        {
          "label": "추가 보급 비용을 내고 사냥터를 줄인다",
          "result": "추가 자원을 투입해 사냥 범위를 좁힌다. 집중적인 화력을 쏟아부을 수 있는 환경을 만든다. 카드: 없음. [포션: 2 획득, 밀도: -1]"
        }
      ]
    },
    {
      "key": "sao_safezone_clue",
      "title": "안전 구역의 모순",
      "story": "안전 구역에서 공격을 받았다는 증언이 돌았다. 증언만으로 규칙이 사라졌다고 단정할 수는 없다. 키리토와 아스나는 장비와 목격담을 따로 확인한다.",
      "intro": "안전 구역에서 공격을 받았다는 증언이 돌았다. 증언만으로 규칙이 사라졌다고 단정할 수는 없다. 키리토와 아스나는 장비와 목격담을 따로 확인한다.",
      "choices": [
        {
          "label": "장비를 조사하며 가공 비용을 낸다",
          "result": "의심스러운 장비의 제작 공정을 정밀 조사한다. 리즈벳의 기술을 빌려 조작 여부를 확인한다. 카드: 리즈벳(가공의 완성도) 획득. [금액: 160 소모]"
        },
        {
          "label": "아스나와 목격담을 확인한다",
          "result": "아스나와 함께 현장을 돌며 목격자들을 대조한다. 엇갈리는 증언 사이의 모순을 찾아낸다. 카드: 아스나(섬광의 사선) 획득."
        },
        {
          "label": "에길에게 확인된 물품을 맡긴다",
          "result": "확보한 증거 물품을 상인 에길에게 전달한다. 그는 물품을 매각하며 정보를 공유해준다. 카드: 없음. [골드: 200 획득]"
        }
      ]
    },
    {
      "key": "zegagrande",
      "title": "제타 그랑데",
      "story": "섬과 섬 사이를 오가는 기공단의 항로에 보급과 의뢰가 쌓인다. 다음 보스를 앞두고 사격 위치, 선체의 안전, 동료의 준비를 나눠 맡는다.",
      "intro": "섬과 섬 사이를 오가는 기공단의 항로에 보급과 의뢰가 쌓인다. 다음 보스를 앞두고 사격 위치, 선체의 안전, 동료의 준비를 나눠 맡는다.",
      "choices": [
        {
          "label": "보수 자재를 사고 카타리나와 화물을 고정한다",
          "result": "카타리나와 협력하여 헐거워진 화물을 고정한다. 선체의 안정성을 확보하기 위한 보수 작업을 마친다. 카드: 카타리나(곁을 지키는 검) 획득. [금액: 200 소모]"
        },
        {
          "label": "오이겐과 위험한 갑판에서 사격 장비를 옮긴다",
          "result": "오이겐의 노련한 움직임으로 무거운 장비를 운반한다. 사격에 최적화된 위치로 장비를 배치한다. 카드: 오이겐(숙련된 사격점) 획득."
        },
        {
          "label": "보급 화물을 정리하고 수고비를 받는다",
          "result": "적재된 보급품을 질서 있게 정리한다. 정리된 물량에 비례하여 수고비를 받는다. 카드: 없음. [골드: 220 획득, 포션: 1 획득]"
        }
      ]
    },
    {
      "key": "gbf_deck_position",
      "title": "확보한 갑판의 자리",
      "story": "화물을 고정한 갑판에 공격 위치가 생겼다. 카타리나는 루리아 곁을 지켜야 하고, 오이겐은 사선이 겹치지 않게 장비를 두려 한다. 당신이 맡을 자리를 고른다.",
      "intro": "화물을 고정한 갑판에 공격 위치가 생겼다. 카타리나는 루리아 곁을 지켜야 하고, 오이겐은 사선이 겹치지 않게 장비를 두려 한다. 당신이 맡을 자리를 고른다.",
      "choices": [
        {
          "label": "오이겐과 사격 위치를 넓힌다",
          "result": "오이겐과 협력하여 사격 범위를 확장한다. 더 넓은 각도에서 적을 타격할 수 있는 위치를 잡는다. 카드: 오이겐(숙련된 사격점) 획득."
        },
        {
          "label": "칼리오스트로에게 장비 조정을 의뢰한다",
          "result": "칼리오스트로에게 정밀한 장비 조정을 요청한다. 연금술적 기술로 사격의 정확도를 높인다. 카드: 칼리오스트로(정밀한 연금 조정) 획득. [금액: 240 소모]"
        },
        {
          "label": "여분의 통로를 닫고 보급을 회수한다",
          "result": "불필요한 통로를 차단하여 방어력을 높인다. 동시에 남은 보급품을 안전하게 회수한다. 카드: 없음. [밀도: -1, 포션: 2 획득]"
        }
      ]
    },
    {
      "key": "gbf_broken_focus",
      "title": "흐트러진 집중",
      "story": "이오가 마법 준비를 다시 하는 동안 적이 모일 통로가 둘로 갈렸다. 힘을 집중할 장소를 넓힐지 안전한 한 곳만 남길지 결정한다. 실제 원작 스킬을 새로 얻는 것은 아니다.",
      "intro": "이오가 마법 준비를 다시 하는 동안 적이 모일 통로가 둘로 갈렸다. 힘을 집중할 장소를 넓힐지 안전한 한 곳만 남길지 결정한다. 실제 원작 스킬을 새로 얻는 것은 아니다.",
      "choices": [
        {
          "label": "이오와 안전한 준비 장소를 마련한다",
          "result": "이오의 마법이 안정적으로 발동하도록 방어적인 위치를 잡는다. 집중된 마력을 효율적으로 방어에 쓴다. 카드: 이오(마법사의 집중) 획득. [금액: 190 소모]"
        },
        {
          "label": "나루메아와 넓은 통로를 맡는다",
          "result": "나루메아와 함께 넓은 구역을 담당한다. 검술을 활용해 광범위한 적의 접근을 차단한다. 카드: 나루메아(끝없는 검의 수련) 획득."
        },
        {
          "label": "베인과 돌아올 길을 지킨다",
          "result": "베인과 협력하여 퇴각 경로를 확보한다. 동료들이 안전하게 돌아올 수 있는 길을 수호한다. 카드: 베인(친구가 돌아올 자리) 획득."
        }
      ]
    },
    {
      "key": "gbf_sealed_report",
      "title": "봉인 무기의 조사 기록",
      "story": "제타가 성정수 조사 기록의 빈 부분을 확인하자고 한다. 조사 대상의 위험을 모른 채 강한 무기만 요구할 수는 없다. 무엇을 맡을지 선택한다.",
      "intro": "제타가 성정수 조사 기록의 빈 부분을 확인하자고 한다. 조사 대상의 위험을 모른 채 강한 무기만 요구할 수는 없다. 무엇을 맡을지 선택한다.",
      "choices": [
        {
          "label": "제타와 위험 구역의 기록을 확인한다",
          "result": "제타와 함께 위험 구역의 기록을 대조한다. 봉인 무기의 위험성에 대한 정확한 정보를 수집한다. 카드: 제타(봉인 무기의 사선) 획득."
        },
